const contractAjv=new Ajv({strict:true,allErrors:true});addFormats(contractAjv);
const contractChecks=new Map<string,any>();
function assertContract(name:string,value:unknown){let check=contractChecks.get(name);if(!check){check=contractAjv.compile(contracts[name]);contractChecks.set(name,check);}assert.ok(check(value),`${name} response violates OpenAPI: ${JSON.stringify(check.errors)}`);}
const db = process.env.TEST_DATABASE_URL;
if (!db) throw new Error('TEST_DATABASE_URL must point to an isolated migrated test database');
const port=46000+Math.floor(Math.random()*1500),base=`http://127.0.0.1:${port}`;
let child:ChildProcess;
async function stopChild(){if(child.exitCode===null&&child.signalCode===null){const done=new Promise<void>(resolve=>child.once('exit',()=>resolve()));child.kill('SIGTERM');await done;}}
async function ready(){for(let i=0;i<100;i++){try{const r=await fetch(base+'/health');if(r.ok)return;}catch{}await new Promise(r=>setTimeout(r,50));}throw new Error('API did not become healthy');}
function client(){let cookie='',csrf='';return {
 async call(method:string,url:string,body?:unknown,extra:Record<string,string>={}){const headers:Record<string,string>={Origin:'http://localhost:3000',...extra};if(cookie)headers.Cookie=cookie;if(csrf&&method!=='GET')headers['X-CSRF-Token']=csrf;if(body!==undefined)headers['Content-Type']='application/json';const r=await fetch(base+url,{method,headers,body:body===undefined?undefined:JSON.stringify(body),redirect:'manual'});const set=r.headers.get('set-cookie');if(set)cookie=set.split(';')[0]!;const payload=r.status===204?null:await r.json();if(payload?.csrfToken)csrf=payload.csrfToken;return {r,payload};},
 get csrf(){return csrf;},get cookie(){return cookie;}
};}
const key=()=>randomUUID();
