  const revPath=`/v1/workspaces/${wid}/projects/${pid}/revision`;x=await a.call('GET',revPath);assert.equal(x.r.status,200);assert.equal(x.r.headers.get('etag'),'"rev-0"');const doc=x.payload.document;
