  const copy=await a.call('GET',`/v1/workspaces/${wid}/projects/${copyId}/revision`);const latest=await a.call('GET',revPath);assert.deepEqual(copy.payload.document,{...latest.payload.document,projectId:copyId,revision:0});
  x=await a.call('POST',projectPath+'/duplicate',{name:'Independent copy'},{'Idempotency-Key':duplicateKey});assert.equal(x.payload.id,copyId);
  const newest=await a.call('GET',`/v1/workspaces/${wid}/projects?limit=1`);assert.equal(newest.payload.items[0].id,copyId);assert.ok(newest.payload.nextCursor);
