   const rationalDoc=structuredClone(restored.payload.document);rationalDoc.canvas.frameRate={num:30,den:1};rationalDoc.assets=[{assetId:rationalAsset,versionId:rationalVersion,kind:'video',sha256:rationalSha,status:'ready'}];rationalDoc.sequences[0].durationTick=240000;rationalDoc.sequences[0].tracks[0].clips=[{id:randomUUID(),type:'media',assetVersionId:rationalVersion,startTick:0,durationTick:240000,sourceRange:{inPts:0,outPts:1,timeBase:{num:999999998,den:999999999}},playbackRate:{num:1,den:1},sourceAudio:{enabled:true,gainDb:0},transform:{x:0,y:0,scaleX:1,scaleY:1,rotationDeg:0,opacity:1},effects:[],keyframes:[]}];
   const rational=await a.call('POST',projectPath+'/validate',{document:rationalDoc});assert.equal(rational.r.status,400);assert.equal(rational.payload.error.code,'SOURCE_TIMEBASE_MISMATCH');
