   const cancelKey=key(),cancel=await a.call('POST',`/v1/workspaces/${wid}/jobs/${queuedJob}/cancel`,{},{'Idempotency-Key':cancelKey});assert.equal(cancel.r.status,202);assert.equal(cancel.payload.state,'cancelled');
   const assetState=await sql.query('SELECT state,error_code FROM media_assets WHERE workspace_id=$1 AND id=$2',[wid,queuedAsset]);assert.equal(assetState.rows[0].state,'failed');assert.equal(assetState.rows[0].error_code,'CANCELLED');
