test('in-flight cancellation and worker reclaim after controller crash',{timeout:30000},async()=>{
 const fs=await import('node:fs/promises');const suffix=randomUUID(),store=`/tmp/studio-cancel-store-${suffix}`,work=`/tmp/studio-cancel-work-${suffix}`;
 const env={...process.env,DATABASE_URL:db,PROJECT_SCHEMA_PATH:path.resolve('../../docs/03-frontend/schemas/project-v1.schema.json'),PORT:String(port),API_HOST:'127.0.0.1',APP_ORIGIN:'http://localhost:3000',NODE_ENV:'development',AUTH_LOCAL_ENABLED:'true',SESSION_SECRET:'test-only-secret-at-least-32-characters',MEDIA_LOCAL_ENABLED:'true',STORAGE_ROOT:store,MEDIA_WORK_ROOT:work,MEDIA_WORKER_SCRIPT:path.resolve('test/fixtures/slow_worker.py')};
 child=spawn(process.execPath,[path.resolve('dist/server.js')],{env,stdio:['ignore','pipe','pipe']});const sql=new pg.Client({connectionString:db});
 try{
  await sql.connect();await ready();const a=client();let x=await a.call('POST','/v1/auth/register',{email:`cancel-${suffix}@example.test`,password:'long-password-for-cancel',displayName:'Cancellation Test'});assert.equal(x.r.status,201);const actor=x.payload.user.id;x=await a.call('POST','/v1/workspaces',{name:'Cancellation test'},{'Idempotency-Key':key()});const wid=x.payload.id;
  async function submit(){const id=randomUUID();await sql.query("INSERT INTO jobs(workspace_id,id,actor_id,kind,state,snapshot,sequence,snapshot_id) VALUES($1,$2,$3,'render','queued',$4,1,$5)",[wid,id,actor,JSON.stringify({document:{assets:[]}}),randomUUID()]);return id;}
  async function waitStarts(count:number){for(let i=0;i<250;i++){const text=await fs.readFile(`${work}/worker-starts`,'utf8').catch(()=>'');const ids=text.trim().split('\n').filter(Boolean).map(Number);if(ids.length>=count)return ids;await new Promise(r=>setTimeout(r,40));}throw new Error('Worker did not start');}
  async function waitFor(id:string,state:string){for(let i=0;i<250;i++){const r=await a.call('GET',`/v1/workspaces/${wid}/jobs/${id}`);if(r.payload.state===state)return r.payload;await new Promise(r=>setTimeout(r,40));}throw new Error('Job did not reach '+state);}
  const first=await submit();await waitStarts(1);await waitFor(first,'running');const envKeys=JSON.parse(await fs.readFile(`${work}/worker-env.json`,'utf8'));assert.ok(!envKeys.includes('DATABASE_URL'));assert.ok(!envKeys.includes('SESSION_SECRET'));
  const request=await a.call('POST',`/v1/workspaces/${wid}/jobs/${first}/cancel`,{},{'Idempotency-Key':key()});assert.equal(request.r.status,202);assert.ok(['cancel_requested','cancelled'].includes(request.payload.state));await waitFor(first,'cancelled');let count=await sql.query('SELECT count(*)::integer AS n FROM render_artifacts WHERE workspace_id=$1 AND job_id=$2',[wid,first]);assert.equal(count.rows[0].n,0);
  const second=await submit();const starts=await waitStarts(2);await waitFor(second,'running');const oldLease=(await sql.query('SELECT lease_token FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,second])).rows[0].lease_token;const oldPid=starts[1]!;
  const exited=new Promise<void>(resolve=>child.once('exit',()=>resolve()));child.kill('SIGKILL');await exited;try{process.kill(-oldPid,'SIGTERM');}catch{}await sql.query("UPDATE jobs SET lease_expires_at=now()-interval '1 second' WHERE workspace_id=$1 AND id=$2",[wid,second]);
  child=spawn(process.execPath,[path.resolve('dist/server.js')],{env,stdio:['ignore','pipe','pipe']});await ready();await waitStarts(3);const retried=await waitFor(second,'running');assert.equal(retried.attempt,2);await assert.rejects(fs.stat(`${work}/job-${second}-${oldLease}`),{code:'ENOENT'});
  x=await a.call('POST',`/v1/workspaces/${wid}/jobs/${second}/cancel`,{},{'Idempotency-Key':key()});assert.equal(x.r.status,202);await waitFor(second,'cancelled');count=await sql.query('SELECT count(*)::integer AS n FROM render_artifacts WHERE workspace_id=$1 AND job_id=$2',[wid,second]);assert.equal(count.rows[0].n,0);
  const third=await submit();await waitStarts(4);await waitFor(third,'running');const gracefulLease=(await sql.query('SELECT lease_token FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,third])).rows[0].lease_token;const gracefullyStopped=new Promise<void>(resolve=>child.once('exit',()=>resolve()));child.kill('SIGTERM');await gracefullyStopped;
  const queued=await sql.query('SELECT state,lease_token FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,third]);assert.equal(queued.rows[0].state,'queued');assert.equal(queued.rows[0].lease_token,null);await assert.rejects(fs.stat(`${work}/job-${third}-${gracefulLease}`),{code:'ENOENT'});
  child=spawn(process.execPath,[path.resolve('dist/server.js')],{env,stdio:['ignore','pipe','pipe']});await ready();await waitStarts(5);const gracefulRetry=await waitFor(third,'running');assert.equal(gracefulRetry.attempt,2);x=await a.call('POST',`/v1/workspaces/${wid}/jobs/${third}/cancel`,{},{'Idempotency-Key':key()});assert.equal(x.r.status,202);await waitFor(third,'cancelled');

 }finally{await stopChild();await sql.end();await fs.rm(store,{recursive:true,force:true});await fs.rm(work,{recursive:true,force:true});}
});

test('progress arriving after a lease is cancelled cannot crash the API',{timeout:15000},async()=>{
 const fs=await import('node:fs/promises');const suffix=randomUUID(),store=`/tmp/studio-progress-store-${suffix}`,work=`/tmp/studio-progress-work-${suffix}`;
 child=spawn(process.execPath,[path.resolve('dist/server.js')],{env:{...process.env,DATABASE_URL:db,PROJECT_SCHEMA_PATH:path.resolve('../../docs/03-frontend/schemas/project-v1.schema.json'),PORT:String(port),API_HOST:'127.0.0.1',APP_ORIGIN:'http://localhost:3000',NODE_ENV:'development',AUTH_LOCAL_ENABLED:'true',SESSION_SECRET:'test-only-secret-at-least-32-characters',MEDIA_LOCAL_ENABLED:'true',STORAGE_ROOT:store,MEDIA_WORK_ROOT:work,MEDIA_WORKER_SCRIPT:path.resolve('test/fixtures/progress_worker.py')},stdio:['ignore','pipe','pipe']});
 const sql=new pg.Client({connectionString:db});
 try{
  await sql.connect();await ready();const a=client();let x=await a.call('POST','/v1/auth/register',{email:`progress-${suffix}@example.test`,password:'long-password-for-progress',displayName:'Progress Test'});assert.equal(x.r.status,201);const actor=x.payload.user.id;x=await a.call('POST','/v1/workspaces',{name:'Progress test'},{'Idempotency-Key':key()});const wid=x.payload.id,jid=randomUUID();
  await sql.query("INSERT INTO jobs(workspace_id,id,actor_id,kind,state,snapshot,sequence,snapshot_id) VALUES($1,$2,$3,'render','queued',$4,1,$5)",[wid,jid,actor,JSON.stringify({document:{assets:[]}}),randomUUID()]);
  let running=false;for(let i=0;i<100;i++){const row=await sql.query('SELECT state,fraction FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,jid]);if(row.rows[0].state==='running'&&row.rows[0].fraction!==null){running=true;break;}await new Promise(r=>setTimeout(r,30));}assert.ok(running);
  // Simulate cancellation committed by another controller, before this controller observes it.
  await sql.query("UPDATE jobs SET state='cancel_requested' WHERE workspace_id=$1 AND id=$2",[wid,jid]);
  let cancelled=false;for(let i=0;i<100;i++){const row=await sql.query('SELECT state FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,jid]);if(row.rows[0].state==='cancelled'){cancelled=true;break;}await new Promise(r=>setTimeout(r,30));}assert.ok(cancelled,'post-cancellation progress should terminate and finish the job');
  assert.equal((await fetch(base+'/health')).status,200);assert.equal(child.exitCode,null);
  const malformed=randomUUID();await sql.query("INSERT INTO jobs(workspace_id,id,actor_id,kind,state,snapshot,sequence,snapshot_id) VALUES($1,$2,$3,'render','queued',$4,1,$5)",[wid,malformed,actor,JSON.stringify({document:{assets:[],malformedFixture:true}}),randomUUID()]);
  let rejected=false;for(let i=0;i<100;i++){const row=await sql.query('SELECT state,error_code FROM jobs WHERE workspace_id=$1 AND id=$2',[wid,malformed]);if(row.rows[0].state==='failed'){assert.equal(row.rows[0].error_code,'WORKER_PROTOCOL');rejected=true;break;}await new Promise(r=>setTimeout(r,30));}assert.ok(rejected,'malformed worker event must fail safely');assert.equal((await fetch(base+'/health')).status,200);assert.equal(child.exitCode,null);
 }finally{await stopChild();await sql.end();await fs.rm(store,{recursive:true,force:true});await fs.rm(work,{recursive:true,force:true});}
});
